# Generated by homebrew/cask.sh in the PETA Whisper repo — edit that, not this.
cask "peta-whisper" do
  version "1.1.2"
  sha256 "e11d384943261d644931bc961650cfd3e5f10133932c2ac3e32c452c73b5c3d7"

  # The same DMG the website's Download button serves. Versioned and immutable,
  # so the checksum above is good for as long as the file exists.
  url "https://peta-whisper.vercel.app/downloads/PETA-Whisper-#{version}.dmg"
  name "PETA Whisper"
  desc "Hold fn, talk, and the words appear wherever your cursor is"
  homepage "https://peta-whisper.vercel.app/"

  livecheck do
    url "https://peta-whisper.vercel.app/appcast.json"
    strategy :json do |json|
      json["version"]
    end
  end

  # An instruction to brew to keep its hands off, not a claim about the app.
  # `brew upgrade --cask` uninstalls before it reinstalls, and macOS drops an
  # app's privacy grants the moment its bundle stops existing; Accessibility and
  # Input Monitoring are the two this app cannot work without. The app's own
  # updater (Updater.swift) carries it from here, swapping the bundle in place.
  auto_updates true
  # build.sh is one swiftc call on the host, so the binary is thin arm64.
  depends_on arch: :arm64
  # LSMinimumSystemVersion, as a floor.
  depends_on macos: :ventura

  app "PETA Whisper.app"

  # Ad-hoc signed and not notarised: Gatekeeper refuses a quarantined copy
  # outright, and brew quarantines every download. Dropping the attribute here
  # is what `--no-quarantine` does, without anyone having to know to pass it.
  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "{{appdir}}/PETA Whisper.app"]
  end

  uninstall launchctl: "com.openwispr.app",
            quit:      "com.openwispr.app"

  # Your API key, dictionary and history live in ~/.config/openwispr. zap is
  # the "remove every trace" command, so that folder goes with it.
  zap trash: [
    "~/.config/openwispr",
    "~/Library/LaunchAgents/com.openwispr.app.plist",
  ]

  caveats <<~EOS
    On first run, paste an OpenRouter key (openrouter.ai/keys) under
    Transcription in Settings, then allow Accessibility, Input Monitoring and
    Microphone when macOS asks.

    The app updates itself and asks before installing anything. Let it: a
    `brew upgrade --cask --greedy` would delete the bundle and take the
    permission grants with it. Because each build is ad-hoc signed, macOS may
    ask you to allow Accessibility and Input Monitoring again after an update.
  EOS
end
